//! The `gateway!` macro: the single line an addon writes.
//!
//! It turns a list of `#[service]` proxies into the two things an addon needs:
//! the [`GatewayService`](crate::GatewayService) table this crate dispatches to,
//! and the eight `#[napi]` functions the JavaScript side calls. Everything else
//! — the bridge, the lifecycle, the error codes, the dispatch — lives in this
//! crate, so an addon carries no logic of its own.

/// Declares the services of a Node.js gateway addon and its N-API surface.
///
/// The arguments are the **proxies** generated by `#[service]`, in any order:
///
/// ```rust,ignore
/// ice_rpc_nodejs::gateway! {
///     my_services::ConfigServiceProxy,
///     my_services::OrdersServiceProxy,
/// }
/// ```
///
/// # Requirements on the addon crate
///
/// - `crate-type = ["cdylib"]` and a `build.rs` calling `napi_build::setup()`;
/// - direct dependencies on `napi` and `napi-derive` (the `#[napi]` attribute
///   and the generated code name them by absolute path);
/// - the service crate must enable the JSON view of its proxies (the
///   `ice-rpc/json` feature, reached through the service crate's own feature).
///
/// # Generated
///
/// - `__ICE_RPC_GATEWAY_SERVICES`: the service table;
/// - `registerService`, `init`, `callService`, `callServiceStream`,
///   `emitNodejsEvent`, `resolveNodejsCall`, `shutdown` and `version`.
#[macro_export]
macro_rules! gateway {
    ($($proxy:ty),* $(,)?) => {
        /// The services this addon serves, read by every entry point below.
        #[doc(hidden)]
        pub static __ICE_RPC_GATEWAY_SERVICES: &[$crate::GatewayService] = &[
            $(
                $crate::GatewayService {
                    name: <$proxy as $crate::ice_rpc::codegen::ServiceNamed>::SERVICE_NAME,
                    provide: || ::std::boxed::Box::pin(async {
                        let proxy = <$proxy>::provide_json();
                        $crate::ice_rpc::locator().register(proxy).await;
                    }),
                    invoker: || ::std::boxed::Box::pin(async {
                        $crate::ice_rpc::locator()
                            .get::<$proxy>()
                            .await
                            .map(|proxy| proxy as ::std::sync::Arc<dyn $crate::ice_rpc::codegen::JsonInvoker>)
                    }),
                },
            )*
        ];

        /// Registers a Node.js provider service by its logical name.
        ///
        /// To call **before** `init`. Refuses an unknown name with
        /// `E_UNKNOWN_SERVICE` and a registration after `init` with
        /// `E_GATEWAY_STATE`.
        #[::napi_derive::napi]
        pub fn register_service(service_name: ::std::string::String) -> ::napi::Result<()> {
            $crate::register_service_impl(__ICE_RPC_GATEWAY_SERVICES, service_name)
        }

        /// Initializes the gateway: bridge, dispatch loop, service announcement.
        ///
        /// The callback is called as `(err, call)` where `call` is
        /// `{ correlationId, service, method, args }` and `args` is a native JS
        /// value.
        #[::napi_derive::napi]
        pub fn init(
            callback: ::napi::bindgen_prelude::Function<
                '_,
                $crate::serde_json::Value,
                ::napi::bindgen_prelude::Unknown<'static>,
            >,
        ) -> ::napi::Result<()> {
            $crate::init_impl(callback)
        }

        /// Calls a method of a remote IPC service and resolves with its first value.
        #[::napi_derive::napi]
        pub fn call_service(
            service_name: ::std::string::String,
            method_name: ::std::string::String,
            args: $crate::serde_json::Value,
        ) -> ::napi::Result<::napi::bindgen_prelude::AsyncTask<$crate::CallServiceTask>> {
            $crate::call_service_impl(__ICE_RPC_GATEWAY_SERVICES, service_name, method_name, args)
        }

        /// Calls a method of a remote IPC service and resolves with every value it emits.
        #[::napi_derive::napi]
        pub fn call_service_stream(
            service_name: ::std::string::String,
            method_name: ::std::string::String,
            args: $crate::serde_json::Value,
        ) -> ::napi::Result<::napi::bindgen_prelude::AsyncTask<$crate::CallServiceStreamTask>> {
            $crate::call_service_stream_impl(
                __ICE_RPC_GATEWAY_SERVICES,
                service_name,
                method_name,
                args,
            )
        }

        /// Pushes an intermediate event of a call, keeping it open.
        ///
        /// `emitNodejsEvent(correlationId, { data })` — one value, one wire
        /// sample. The terminal event belongs to `resolveNodejsCall`.
        #[::napi_derive::napi]
        pub fn emit_nodejs_event(
            correlation_id: ::std::string::String,
            event: $crate::serde_json::Value,
        ) -> ::napi::Result<()> {
            $crate::emit_nodejs_event_impl(correlation_id, event)
        }

        /// Answers a call with its terminal event and closes it.
        ///
        /// `resolveNodejsCall(correlationId, { data } | { error } | {})`: the
        /// closing event is **built from the envelope**, never stated as a
        /// `type`.
        #[::napi_derive::napi]
        pub fn resolve_nodejs_call(
            correlation_id: ::std::string::String,
            event: $crate::serde_json::Value,
        ) -> ::napi::Result<()> {
            $crate::resolve_nodejs_call_impl(correlation_id, event)
        }

        /// Stops the gateway and releases the IPC resources.
        #[::napi_derive::napi]
        pub fn shutdown() -> ::napi::Result<::napi::bindgen_prelude::AsyncTask<$crate::ShutdownTask>> {
            $crate::shutdown_impl()
        }

        /// Returns the addon, `ice-rpc` and protocol versions actually compiled in.
        #[::napi_derive::napi]
        pub fn version() -> ::std::string::String {
            $crate::version_string(env!("CARGO_PKG_NAME"), env!("CARGO_PKG_VERSION"))
        }
    };
}
